class ImportedNameOrigin:
    """A selected alias of the actual import declaration in its source module."""

    declaration: ImportDeclarationABC
    alias: ImportAliasRequirement
    module_identity: PythonModulePathIdentity

    def __post_init__(self) -> None:
        if not any(self.alias is alias for alias in self.declaration.aliases):
            raise ValueError("Import origin requires an alias of its declaration")
        if self.declaration.bound_name(self.alias) is None:
            raise ValueError("A star request has no explicit individual binding")

    @property
    def bound_name(self) -> str:
        name = self.declaration.bound_name(self.alias)
        assert name is not None
        return name

    @property
    def qualified_name(self) -> str | None:
        return self.declaration.qualified_name(self.alias, self.module_identity)

    @property
    def requested_module_name(self) -> str | None:
        return self.declaration.requested_module_name(self.alias, self.module_identity)

    @property
    def source(self) -> str:
        return self.declaration.source_for((self.alias,))

class ImportBoundNameProjection:
    """AST bridge to the declaration owning import syntax and binding rules."""

    statement: ast.Import | ast.ImportFrom

    @cached_property
    def declaration(self) -> ImportDeclarationABC:
        aliases = tuple(ImportAliasRequirement.from_alias(alias) for alias in self.statement.names)
        if isinstance(self.statement, ast.Import):
            return ModuleImportDeclaration(aliases)
        return FromImportDeclaration(aliases, ImportFromModuleName.from_node(self.statement))

    def names(self) -> tuple[str, ...]:
        return self.declaration.names()

    def origins(self, module_identity: PythonModulePathIdentity) -> tuple[ImportedNameOrigin, ...]:
        return self.declaration.origins(module_identity)

    def name_sources(self) -> tuple[tuple[str, str], ...]:
        return self.declaration.name_sources()

    def alias_bound_name(self, alias: ast.alias) -> str:
        return self.declaration.bound_name(ImportAliasRequirement.from_alias(alias)) or ""

def validate_import_origin(self, origin: ImportedNameOrigin | None) -> None:
    if origin is None:
        raise ValueError("Import mutations require their source declaration")

def resolve_source(
    self, resolver: CompactBindingResolverABC[TargetResolutionT],
    context: CompactFlowContext, reference: LexicalValueReference,
    binding: CompactMutation, pending: frozenset[CompactBindingVisit],
) -> TargetResolutionT:
    return resolver._imported_name_resolution(context, reference, binding, pending)

