def _imported_name_resolution(
    self, context: CompactFlowContext, reference: LexicalValueReference,
    binding: CompactMutation,
    pending: frozenset[CompactBindingVisit],
) -> TargetResolutionT:
    raise NotImplementedError

def _record_mutation(
    self, target: CompactAssignmentTargetABC, node: SourcePositionedNode,
    kind: CompactMutationKind | None = None,
) -> CompactMutation:
    mutation = CompactMutation(
        target=target, kind=self.mutation_kind if kind is None else kind,
        position=self._position(), line=node.lineno,
    )
    self.mutations.append(mutation)
    return mutation

def visit_Import(self, node: ast.Import | ast.ImportFrom) -> None:
    for origin in ImportBoundNameProjection(node).origins(self.module_identity):
        self._record_mutation(CompactImportTarget(origin), node, CompactMutationKind.IMPORT)

def _imported_name_resolution(
    self, context: CompactFlowContext, reference: LexicalValueReference,
    binding: CompactMutation,
    pending: frozenset[CompactBindingVisit],
) -> CompactCallTargetResolution:
    origin = binding.imported_origin
    assert origin is not None
    qualified_name = origin.qualified_name
    if qualified_name is None:
        return self._possible_binding_resolution(
            context, reference, CompactFunctionTargetResolutionViolation.MISSING_DECLARATION, pending,
        )
    return self._function_resolution_for_symbol(
        ".".join((qualified_name, *reference.attribute_path)), pending,
    )

def origins(self, module_identity: PythonModulePathIdentity) -> tuple[ImportedNameOrigin, ...]:
    return tuple(
        ImportedNameOrigin(self, index, module_identity)
        for index, alias in enumerate(self.aliases) if self.bound_name(alias) is not None
    )

class ImportedNameOrigin:
    """A selected source position in the actual import declaration."""

    declaration: ImportDeclarationABC
    alias_index: int
    module_identity: PythonModulePathIdentity

    def __post_init__(self) -> None:
        if not 0 <= self.alias_index < len(self.declaration.aliases):
            raise ValueError("Import origin requires an alias position within its declaration")
        if self.declaration.bound_name(self.alias) is None:
            raise ValueError("A star request has no explicit individual binding")

    @property
    def alias(self) -> ImportAliasRequirement:
        return self.declaration.aliases[self.alias_index]

    @property
    def bound_name(self) -> str:
        name = self.declaration.bound_name(self.alias)
        assert name is not None
        return name

    @property
    def qualified_name(self) -> str | None:
        return self.declaration.qualified_name(self.alias, self.module_identity)

    @property
    def requested_module_name(self) -> str | None:
        return self.declaration.requested_module_name(self.alias, self.module_identity)

    @property
    def source(self) -> str:
        return self.declaration.source_for((self.alias,))
